# Validate inputs
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not isinstance(arr, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if arr.ndim != 2:
        raise ValueError("Input must be a 2D matrix")
    if 0 in arr.shape:
        raise ValueError("Input matrix must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError("Input contains non-finite values")
    if not np.all(arr <= 0):
        raise ValueError("Input contains positive values")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Input matrices must have the same shape")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter must not be a boolean")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be finite and nonnegative")

# Compute sums over horizon
sum_with = np.sum(logp_with_result, axis=1)
sum_call = np.sum(logp_call_only, axis=1)
sum_no = np.sum(logp_no_call, axis=1)

# Improvement: reduction in loss = sum_with - sum_no (since loss = -sum, so improvement = -sum_no - (-sum_with) = sum_with - sum_no)
improvement = sum_with - sum_no

# Condition: improvement >= tau_filter and loss_call_only <= loss_no_call  i.e., sum_call >= sum_no
keep_mask = (improvement >= tau_filter) & (sum_call >= sum_no)

return keep_mask, improvement
